pub fn save_session_to_path(
    path: &Path,
    session: &PersistedWorkspaceSession,
) -> Result<(), IpcError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to create directory for session state: {}", e),
            )
        })?;
    }

    let serialized = serde_json::to_string_pretty(session).map_err(|e| {
        IpcError::new(
            IpcErrorCode::ParseError,
            format!("Failed to serialize session state: {}", e),
        )
    })?;

    let tmp_path = path.with_extension("json.tmp");

    // Durable atomic write: write -> sync_all -> rename -> parent fsync
    {
        use std::io::Write;
        let mut file = File::create(&tmp_path).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to create temporary session file: {}", e),
            )
        })?;
        file.write_all(serialized.as_bytes()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to write session state: {}", e),
            )
        })?;
        file.sync_all().map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to fsync temporary session file: {}", e),
            )
        })?;
    }

    fs::rename(&tmp_path, path).map_err(|e| {
        IpcError::new(
            IpcErrorCode::IoError,
            format!("Failed to atomically rename session state file: {}", e),
        )
    })?;

    // Parent directory fsync
    if let Some(parent) = path.parent() {
        if let Ok(dir_file) = File::open(parent) {
            let _ = dir_file.sync_all();
        }
    }

    Ok(())
}

pub fn load_session_from_path(path: &Path) -> Result<Option<PersistedWorkspaceSession>, IpcError> {
    if !path.exists() {
        return Ok(None);
    }

    let content = fs::read_to_string(path).map_err(|e| {
        IpcError::new(
            IpcErrorCode::IoError,
            format!("Failed to read session state file: {}", e),
        )
    })?;

    match serde_json::from_str::<PersistedWorkspaceSession>(&content) {
        Ok(session) => {
            if !(1..=3).contains(&session.version) {
                eprintln!(
                    "Warning: Unsupported session version {}, ignoring.",
                    session.version
                );
                return Ok(None);
            }
            Ok(Some(session))
        }
        Err(err) => {
            let backup_path = path.with_extension("json.corrupted");
            let _ = fs::rename(path, backup_path);
            eprintln!(
                "Warning: Session state file was corrupted ({}), moved to backup.",
                err
            );
            Ok(None)
        }
    }
}

pub fn clear_session_from_path(path: &Path) -> Result<(), IpcError> {
    if path.exists() {
        fs::remove_file(path).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to remove session state file: {}", e),
            )
        })?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn test_session_save_load_clear_cycle() {
        let dir = tempdir().unwrap();
        let session_file = dir.path().join("session_state.json");

        let mut workspaces = HashMap::new();
        workspaces.insert(
            "default".to_string(),
            PersistedWorkspace {
                workspace_id: "default".to_string(),
                repo_root: PathBuf::from("/tmp/repo"),
                worktrees: vec![PersistedWorktree {
                    path: "/tmp/repo".to_string(),
                    branch: "main".to_string(),
                    head: "abcdef".to_string(),
                    is_main: true,
                    is_locked: false,
                }],
                active_worktree_path: Some("/tmp/repo".to_string()),
                layout: PersistedLayout {
                    split_mode: "none".to_string(),
                    primary_tab_id: Some("tab-1".to_string()),
                    secondary_tab_id: None,
                    active_tab_id: Some("tab-1".to_string()),
                    tabs: vec![PersistedTab {
                        id: "tab-1".to_string(),
                        kind: None,
                        label: "main".to_string(),
                        pinned: None,
                        terminal: None,
                        browser: None,
                        custom_title: None,
                        session_id: Some("term-1".to_string()),
                        worktree_path: Some("/tmp/repo".to_string()),
                        pane_tree: None,
                        session_ids_by_leaf_id: None,
                        active_leaf_id: None,
                        expanded_leaf_id: None,
                        extra: HashMap::new(),
                    }],
                    tab_groups: None,
                    tab_group_layout: None,
                    focused_group_id: None,
                    layouts_by_tab_id: None,
                    extra: HashMap::new(),
                },
                worktree_layouts: None,
                layout_by_worktree: None,
                terminal_sessions: HashMap::new(),
                extra: HashMap::new(),
            },
        );

        let session = PersistedWorkspaceSession {
            version: 1,
            timestamp: 1234567890,
            active_workspace_id: "default".to_string(),
            workspaces,
            extra: HashMap::new(),
        };

        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_none());

        save_session_to_path(&session_file, &session).unwrap();
        assert!(session_file.exists());

        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_some());
        let loaded_session = loaded.unwrap();
        assert_eq!(loaded_session.version, 1);
        assert_eq!(loaded_session.active_workspace_id, "default");
        assert_eq!(
            loaded_session.workspaces["default"].repo_root,
            PathBuf::from("/tmp/repo")
        );

        clear_session_from_path(&session_file).unwrap();
        assert!(!session_file.exists());
        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn test_corrupted_session_recovery() {
        let dir = tempdir().unwrap();
        let session_file = dir.path().join("session_state.json");

        fs::write(&session_file, "{ broken json ...").unwrap();

        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_none());
        assert!(!session_file.exists());
        assert!(dir.path().join("session_state.json.corrupted").exists());
    }
}

import type {
  LayoutState,
  TabGroup,
  TabGroupLayoutNode,
  TabPaneLayout,
  WorkspaceTab,
} from "../lib/types";
import {
  clampRatio,
  collectLeafIds,
  createLeafNode,
  equalizeRatios,
  findFirstLeafId,
  findSiblingLeafId,
  type PaneDirection,
  removeLeaf,
  setRatioAtPath,
  splitLeaf,
  swapLeaves,
} from "./paneTree";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: WorkspaceTab; sessionId?: string; activate?: boolean }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: WorkspaceTab }
  | { type: "ACTIVATE_TAB"; tabId: string }
  | { type: "REORDER_TAB"; tabId: string; targetIndex: number }
  | { type: "RENAME_TAB"; tabId: string; label: string }
  | { type: "SET_TAB_PINNED"; tabId: string; pinned: boolean }
  | {
      type: "SPLIT_PANE";
      tabId: string;
      targetLeafId?: string;
      direction: PaneDirection;
      newLeafId?: string;
      sessionId: string;
      position?: "first" | "second";
      ratio?: number;
    }
  | {
      type: "MOVE_TAB_TO_GROUP";
      sourceTabId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "MOVE_TAB_TO_SPLIT";
      sourceTabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position?: "first" | "second";
      ratio?: number;
    }
  | {
      type: "DETACH_PANE_TO_TAB";
      sourceTabId: string;
      leafId: string;
      newTab: WorkspaceTab;
      targetGroupId?: string;
      targetIndex?: number;
    }
  | { type: "SET_TAB_GROUP_RATIO"; path: string; ratio: number }
  | { type: "CLOSE_PANE"; tabId: string; leafId: string; replacementSessionId?: string }
  | { type: "FOCUS_PANE"; tabId: string; leafId: string }
  | { type: "SET_PANE_RATIO"; tabId: string; path: string; ratio: number }
  | { type: "SWAP_PANES"; tabId: string; sourceLeafId: string; targetLeafId: string }
  | { type: "TOGGLE_PANE_EXPANDED"; tabId: string; leafId: string }
  | { type: "EQUALIZE_PANES"; tabId: string };

export function createLayoutState(tabs: WorkspaceTab[] = [], activeTabId?: string | null): LayoutState {
  const layoutsByTabId: Record<string, TabPaneLayout> = {};
  for (const tab of tabs) {
    const leafId = "leaf-init";
    const sessionId = tab.kind === "browser" ? "" : tab.sessionId;
    layoutsByTabId[tab.id] = {
      root: createLeafNode(leafId),
      activeLeafId: leafId,
      expandedLeafId: null,
      sessionIdsByLeafId: { [leafId]: sessionId },
    };
  }

  return normalizeLayoutInternal(
    {
      tabs,
      activeTabId: activeTabId ?? tabs[0]?.id ?? null,
      layoutsByTabId,
    },
    true,
  );
}

export function getTabGroups(state: LayoutState): Record<string, TabGroup> {
  return normalizeLayout(state).tabGroups ?? {};
}

export function getTabGroupLayout(state: LayoutState): TabGroupLayoutNode | null {
  return normalizeLayout(state).tabGroupLayout ?? null;
}

export function getFocusedGroupId(state: LayoutState): string | null {
  return normalizeLayout(state).focusedGroupId ?? null;
}

export function getGroupForTab(state: LayoutState, tabId: string): TabGroup | null {
  const normalized = normalizeLayout(state);
  return findGroupContainingTab(normalized.tabGroups ?? {}, tabId);
}

export function getTabsForGroup(state: LayoutState, groupId: string): WorkspaceTab[] {
  const normalized = normalizeLayout(state);
  const group = normalized.tabGroups?.[groupId];
  if (!group) return [];
