function createInitialState(worktrees: Worktree[]): WorkspaceState {
  return {
    worktrees,
    activeWorktreePath: worktrees[0]?.path ?? null,
    sessions: {},
    layout: createLayoutState(),
    worktreeLayouts: {},
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

function workspaceReducer(state: WorkspaceState, action: WorkspaceAction): WorkspaceState {
  switch (action.type) {
    case "RESTORE_WORKSPACE":
      return {
        ...action.state,
        worktreeLayouts: action.state.worktreeLayouts ?? {},
        unreadTabIds: action.state.unreadTabIds ?? {},
        unreadWorktreePaths: action.state.unreadWorktreePaths ?? {},
        activityBySessionId: action.state.activityBySessionId ?? {},
      };
    case "SET_WORKTREES": {
      const validWorktreePaths = new Set(action.worktrees.map((worktree) => worktree.path));
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).filter(([, session]) => validWorktreePaths.has(sessionWorktreePath(session))),
      );
      const activityBySessionId = Object.fromEntries(
        Object.entries(state.activityBySessionId ?? {}).filter(([sessionId]) => Boolean(sessions[sessionId])),
      );
      let layout = state.layout;
      for (const tab of state.layout.tabs) {
        const hasRetainedSession = [...getTabSessionIdsForLayout(state.layout, tab.id)].some((sessionId) => Boolean(sessions[sessionId]));
        if (tab.kind !== "browser" && !hasRetainedSession) {
          layout = layoutReducer(layout, { type: "CLOSE_TAB", tabId: tab.id });
        }
      }
      const worktreeLayouts: Record<string, LayoutState> = {};
      for (const [path, parkedLayout] of Object.entries(state.worktreeLayouts ?? {})) {
        if (!validWorktreePaths.has(path)) continue;
        let cleanedLayout = parkedLayout;
        for (const tab of parkedLayout.tabs) {
          const hasRetainedSession = [...getTabSessionIdsForLayout(parkedLayout, tab.id)].some((sessionId) => Boolean(sessions[sessionId]));
          if (tab.kind !== "browser" && !hasRetainedSession) {
            cleanedLayout = layoutReducer(cleanedLayout, { type: "CLOSE_TAB", tabId: tab.id });
          }
        }
        worktreeLayouts[path] = cleanedLayout;
      }
      let activeWorktreePath = state.activeWorktreePath;
      if (!action.worktrees.some((worktree) => worktree.path === activeWorktreePath)) {
        activeWorktreePath = action.worktrees[0]?.path ?? null;
        if (activeWorktreePath && worktreeLayouts[activeWorktreePath]) {
          layout = worktreeLayouts[activeWorktreePath];
          delete worktreeLayouts[activeWorktreePath];
        }
      }
      const allTabs = [...layout.tabs, ...Object.values(worktreeLayouts).flatMap((l) => l.tabs)];
      const unreadTabIds = Object.fromEntries(
        Object.entries(state.unreadTabIds).filter(([tabId]) => allTabs.some((tab) => tab.id === tabId)),
      );
      const unreadWorktreePaths = Object.fromEntries(
        Object.entries(state.unreadWorktreePaths).filter(([path]) => validWorktreePaths.has(path)),
      );
      return {
        ...state,
        worktrees: action.worktrees,
        activeWorktreePath,
        sessions,
        layout,
        worktreeLayouts,
        activityBySessionId,
        unreadTabIds,
        unreadWorktreePaths,
      };
    }
    case "UPDATE_BROWSER_TAB": {
      const inActive = state.layout.tabs.some((tab) => tab.id === action.tabId && tab.kind === "browser");
      if (inActive) {
        const tabs = state.layout.tabs.map((tab) => {
          if (tab.id === action.tabId && tab.kind === "browser") return { ...tab, ...action.updates };
          return tab;
        });
        return { ...state, layout: { ...state.layout, tabs } };
      }
      const worktreeLayouts = { ...(state.worktreeLayouts ?? {}) };
      for (const [wtPath, parkedLayout] of Object.entries(worktreeLayouts)) {
        if (parkedLayout.tabs.some((tab) => tab.id === action.tabId && tab.kind === "browser")) {
          const tabs = parkedLayout.tabs.map((tab) => {
            if (tab.id === action.tabId && tab.kind === "browser") return { ...tab, ...action.updates };
            return tab;
          });
          worktreeLayouts[wtPath] = { ...parkedLayout, tabs };
        }
      }
      return { ...state, worktreeLayouts };
    }
    case "SELECT_WORKTREE": {
      if (!state.worktrees.some((worktree) => worktree.path === action.path)) return state;
      if (action.path === state.activeWorktreePath) {
        const unreadWorktreePaths = { ...state.unreadWorktreePaths };
        delete unreadWorktreePaths[action.path];
        const unreadTabIds = { ...state.unreadTabIds };
        for (const tab of state.layout.tabs) {
          delete unreadTabIds[tab.id];
        }
        return { ...state, unreadTabIds, unreadWorktreePaths };
      }

      const nextWorktreeLayouts = { ...(state.worktreeLayouts ?? {}) };
      if (state.activeWorktreePath) {
        nextWorktreeLayouts[state.activeWorktreePath] = state.layout;
      }
      const nextLayout = nextWorktreeLayouts[action.path] ?? createLayoutState();
      delete nextWorktreeLayouts[action.path];

      const unreadWorktreePaths = { ...state.unreadWorktreePaths };
      delete unreadWorktreePaths[action.path];
      const unreadTabIds = { ...state.unreadTabIds };
      for (const tab of nextLayout.tabs) {
        delete unreadTabIds[tab.id];
      }
      return {
        ...state,
        activeWorktreePath: action.path,
        layout: nextLayout,
        worktreeLayouts: nextWorktreeLayouts,
        unreadTabIds,
        unreadWorktreePaths,
      };
    }
    case "MARK_TAB_UNREAD": {
      if (action.tabId === state.layout.activeTabId) return state;
      const worktreePath = getTabWorktreePath(state, action.tabId);
      return {
        ...state,
        unreadTabIds: { ...state.unreadTabIds, [action.tabId]: true },
        unreadWorktreePaths: worktreePath
          ? { ...state.unreadWorktreePaths, [worktreePath]: true }
          : state.unreadWorktreePaths,
      };
    }
    case "CLEAR_TAB_UNREAD": {
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.tabId];
      return clearWorktreeUnreadWhenRead({ ...state, unreadTabIds }, action.tabId);
    }
    case "MARK_WORKTREE_UNREAD":
      return {
        ...state,
        unreadWorktreePaths: { ...state.unreadWorktreePaths, [action.worktreePath]: true },
      };
    case "CLEAR_WORKTREE_UNREAD": {
      const unreadWorktreePaths = { ...state.unreadWorktreePaths };
      delete unreadWorktreePaths[action.worktreePath];
      return { ...state, unreadWorktreePaths };
    }
    case "ADD_TAB_WITH_SESSION": {
      const sessions = action.session ? { ...state.sessions, [action.session.id]: action.session } : state.sessions;
      const sessionId = action.session?.id;
      const targetWorktreePath =
        action.targetWorktreePath ??
        action.session?.worktreePath ??
        (action.tab.kind === "browser" ? action.tab.worktreePath : undefined);

      if (targetWorktreePath && state.activeWorktreePath && targetWorktreePath !== state.activeWorktreePath) {
        const targetLayout = state.worktreeLayouts?.[targetWorktreePath] ?? createLayoutState();
        const updatedLayout = layoutReducer(targetLayout, { type: "ADD_TAB", tab: action.tab, sessionId });
        return {
          ...state,
          sessions,
          worktreeLayouts: {
            ...(state.worktreeLayouts ?? {}),
            [targetWorktreePath]: updatedLayout,
          },
        };
      }

      return {
        ...state,
        sessions,
        layout: layoutReducer(state.layout, { type: "ADD_TAB", tab: action.tab, sessionId }),
      };
    }
    case "REORDER_TAB":
      return { ...state, layout: layoutReducer(state.layout, action) };
    case "RENAME_TAB":
      return { ...state, layout: layoutReducer(state.layout, action) };
    case "SET_TAB_PINNED":
      return { ...state, layout: layoutReducer(state.layout, action) };
    case "SPLIT_PANE": {
      const layout = layoutReducer(state.layout, {
        type: "SPLIT_PANE",
        tabId: action.tabId,
        targetLeafId: action.targetLeafId,
        direction: action.direction,
        position: action.position,
        newLeafId: action.newLeafId,
        sessionId: action.session.id,
      });
      if (layout === state.layout) return state;
      return {
        ...state,
        sessions: { ...state.sessions, [action.session.id]: action.session },
        layout,
      };
    }
    case "MOVE_TAB_TO_GROUP": {
      const layout = layoutReducer(state.layout, action);
      if (layout === state.layout) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.sourceTabId];
      return { ...state, layout, unreadTabIds };
    }
    case "MOVE_TAB_TO_SPLIT": {
      const layout = layoutReducer(state.layout, action);
      if (layout === state.layout) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.sourceTabId];
      return { ...state, layout, unreadTabIds };
    }
    case "MOVE_TAB_TO_PANE_SPLIT": {
      const layout = moveTabIntoPaneSplit(
        state.layout,
        action.sourceTabId,
        action.targetTabId,
        action.targetLeafId,
        action.direction,
        action.position,
      );
      if (layout === state.layout) return state;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.sourceTabId];
      return { ...state, layout, unreadTabIds };
    }
    case "DETACH_PANE_TO_TAB": {
      const layout = layoutReducer(state.layout, action);
      if (layout === state.layout) return state;
      return { ...state, layout };
    }
    case "CLOSE_PANE": {
      const tab = state.layout.tabs.find((candidate) => candidate.id === action.tabId);
      const tabLayout = state.layout.layoutsByTabId?.[action.tabId];
      if (!tab || tab.kind === "browser" || !tabLayout) return state;
      if (tabLayout.root.type === "leaf" && tabLayout.root.leafId === action.leafId) {
        return workspaceReducer(state, { type: "CLOSE_TAB", tabId: action.tabId });
      }
      const closingSessionId = tabLayout.sessionIdsByLeafId[action.leafId];
      let layout = layoutReducer(state.layout, {
        type: "CLOSE_PANE",
        tabId: action.tabId,
        leafId: action.leafId,
      });
      if (layout === state.layout) return state;

      if (closingSessionId === tab.sessionId) {
        const remainingLayout = layout.layoutsByTabId[action.tabId];
        const replacementSessionId = Object.values(remainingLayout?.sessionIdsByLeafId ?? {}).find(Boolean);
        if (replacementSessionId && replacementSessionId !== tab.sessionId) {
          layout = {
            ...layout,
            tabs: layout.tabs.map((candidate) =>
              candidate.id === action.tabId && candidate.kind !== "browser"
                ? { ...candidate, sessionId: replacementSessionId }
                : candidate,
            ),
          };
        }
      }

      const candidateState: WorkspaceState = { ...state, layout };
      if (!closingSessionId || isSessionReferenced(candidateState, closingSessionId)) return candidateState;
      const sessions = { ...state.sessions };
      delete sessions[closingSessionId];
      const activityBySessionId = { ...(state.activityBySessionId ?? {}) };
      delete activityBySessionId[closingSessionId];
      return { ...candidateState, sessions, activityBySessionId };
    }
    case "CLOSE_TAB": {
      const closingSessionIds = getTabSessionIds(state, action.tabId);
      const sessions = { ...state.sessions };
      const activityBySessionId = { ...(state.activityBySessionId ?? {}) };
      for (const sessionId of closingSessionIds) {
        if (isSessionReferencedOutsideTab(state, sessionId, action.tabId)) continue;
        delete sessions[sessionId];
        delete activityBySessionId[sessionId];
      }
      if (action.replacement?.session) sessions[action.replacement.session.id] = action.replacement.session;
      const unreadTabIds = { ...state.unreadTabIds };
      delete unreadTabIds[action.tabId];

      const inActiveLayout = state.layout.tabs.some((t) => t.id === action.tabId);
      let layout = state.layout;
      let worktreeLayouts = state.worktreeLayouts;

      if (inActiveLayout) {
        layout = layoutReducer(state.layout, {
          type: "CLOSE_TAB",
          tabId: action.tabId,
          replacementTab: action.replacement?.tab,
        });
      } else if (worktreeLayouts) {
        const nextWorktreeLayouts = { ...worktreeLayouts };
        for (const [wtPath, parkedLayout] of Object.entries(nextWorktreeLayouts)) {
          if (parkedLayout.tabs.some((t) => t.id === action.tabId)) {
            nextWorktreeLayouts[wtPath] = layoutReducer(parkedLayout, {
              type: "CLOSE_TAB",
              tabId: action.tabId,
              replacementTab: action.replacement?.tab,
            });
          }
        }
        worktreeLayouts = nextWorktreeLayouts;
      }

      const nextState = {
        ...state,
        sessions,
        activityBySessionId,
        unreadTabIds,
        layout,
        worktreeLayouts,
      };
      return clearWorktreeUnreadWhenRead(nextState, action.tabId, state);
    }
    case "ACTIVATE_TAB": {
      if (state.layout.tabs.some((tab) => tab.id === action.tabId)) {
        const unreadTabIds = { ...state.unreadTabIds };
        delete unreadTabIds[action.tabId];
        const nextState = {
          ...state,
          unreadTabIds,
          layout: layoutReducer(state.layout, { type: "ACTIVATE_TAB", tabId: action.tabId }),
        };
        return clearWorktreeUnreadWhenRead(nextState, action.tabId, state);
      }
      for (const [wtPath, parkedLayout] of Object.entries(state.worktreeLayouts ?? {})) {
        if (parkedLayout.tabs.some((tab) => tab.id === action.tabId)) {
          const nextWorktreeLayouts = { ...(state.worktreeLayouts ?? {}) };
          if (state.activeWorktreePath) {
            nextWorktreeLayouts[state.activeWorktreePath] = state.layout;
          }
          delete nextWorktreeLayouts[wtPath];
          const nextLayout = layoutReducer(parkedLayout, { type: "ACTIVATE_TAB", tabId: action.tabId });
          const unreadTabIds = { ...state.unreadTabIds };
          delete unreadTabIds[action.tabId];
          const unreadWorktreePaths = { ...state.unreadWorktreePaths };
          delete unreadWorktreePaths[wtPath];
          const nextState = {
            ...state,
            activeWorktreePath: wtPath,
            layout: nextLayout,
            worktreeLayouts: nextWorktreeLayouts,
            unreadTabIds,
            unreadWorktreePaths,
          };
          return clearWorktreeUnreadWhenRead(nextState, action.tabId, state);
        }
      }
      return state;
    }
    case "FOCUS_PANE": {
      const layout = layoutReducer(state.layout, { type: "FOCUS_PANE", tabId: action.tabId, leafId: action.leafId });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SET_PANE_RATIO": {
      const layout = layoutReducer(state.layout, { type: "SET_PANE_RATIO", tabId: action.tabId, path: action.path, ratio: action.ratio });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SET_TAB_GROUP_RATIO": {
      const layout = layoutReducer(state.layout, { type: "SET_TAB_GROUP_RATIO", path: action.path, ratio: action.ratio });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SWAP_PANES": {
      const layout = layoutReducer(state.layout, { type: "SWAP_PANES", tabId: action.tabId, sourceLeafId: action.sourceLeafId, targetLeafId: action.targetLeafId });
      return layout === state.layout ? state : { ...state, layout };
    }
    case "SESSION_LIFECYCLE": {
      const matchedSessionIds: string[] = [];
      const sessions = Object.fromEntries(
        Object.entries(state.sessions).map(([id, session]) => {
          if (session.backendSessionId !== action.backendSessionId) return [id, session];
          matchedSessionIds.push(id);
          return [id, { ...session, lifecycle: action.lifecycle }];
        }),
      ) as Record<string, TerminalSession>;
      let nextState: WorkspaceState = { ...state, sessions };
      if (action.lifecycle === "exited") {
        for (const sessionId of matchedSessionIds) {
          const current = nextState.activityBySessionId?.[sessionId];
          if (!current || current.state === "done") continue;
          const tabId = findTabIdForSession(nextState, sessionId);
          if (!tabId) continue;
          nextState = applySessionActivity(nextState, tabId, sessionId, { ...current, state: "done" });
        }
      }
      return nextState;
    }
    case "SESSION_TITLE_ACTIVITY": {
      const parsed = parseAgentTitle(action.title);
      const classified = classifyTerminalTitleActivity(action.title);

      if (!classified) {
        if (!state.activityBySessionId?.[action.sessionId]) return state;
        const activityBySessionId = { ...(state.activityBySessionId ?? {}) };
        delete activityBySessionId[action.sessionId];
        return { ...state, activityBySessionId };
      }

      const normalizedTitle = normalizeTerminalTitle(action.title);
      const activity: TerminalActivity = {
        state: classified,
        title: formatTabLabelFromTitle(action.title, normalizedTitle),
        isAgent: Boolean(parsed?.isAgent || classified),
        agentType: parsed?.isAgent ? parsed.agentType : undefined,
      };
      return applySessionActivity(state, action.tabId, action.sessionId, activity);
    }
  }
}

function applySessionActivity(
  state: WorkspaceState,
  tabId: string,
  sessionId: string,
  activity: TerminalActivity,
): WorkspaceState {
  const previous = state.activityBySessionId?.[sessionId];
  if (
    previous &&
    previous.state === activity.state &&
    previous.title === activity.title &&
    previous.isAgent === activity.isAgent &&
    previous.agentType === activity.agentType
  ) {
    return state;
  }

  let nextState: WorkspaceState = {
    ...state,
    activityBySessionId: { ...(state.activityBySessionId ?? {}), [sessionId]: activity },
  };

  if (activity.state === "done" && previous?.state !== "done" && tabId !== state.layout.activeTabId) {
    const worktreePath = sessionWorktreePath(state.sessions[sessionId]) || getTabWorktreePath(state, tabId);
    nextState = {
      ...nextState,
      unreadTabIds: { ...state.unreadTabIds, [tabId]: true },
      unreadWorktreePaths: worktreePath
        ? { ...state.unreadWorktreePaths, [worktreePath]: true }
        : state.unreadWorktreePaths,
    };
  }

  return nextState;
}

function getAllTabs(state: WorkspaceState): WorkspaceTab[] {
  return [...state.layout.tabs, ...Object.values(state.worktreeLayouts ?? {}).flatMap((l) => l.tabs)];
}

function getTabSessionIdsForLayout(layout: LayoutState, tabId: string): Set<string> {
  const tab = layout.tabs.find((candidate) => candidate.id === tabId);
  if (!tab || tab.kind === "browser") return new Set<string>();
  const tabLayout = layout.layoutsByTabId?.[tabId];
  const sessionIds = new Set<string>(Object.values(tabLayout?.sessionIdsByLeafId ?? {}));
  sessionIds.add(tab.sessionId);
  sessionIds.delete("");
  return sessionIds;
}

function getTabSessionIds(state: WorkspaceState, tabId: string): Set<string> {
  const inActive = getTabSessionIdsForLayout(state.layout, tabId);
  if (inActive.size > 0 || state.layout.tabs.some((t) => t.id === tabId)) return inActive;
  for (const layout of Object.values(state.worktreeLayouts ?? {})) {
    const inParked = getTabSessionIdsForLayout(layout, tabId);
    if (inParked.size > 0 || layout.tabs.some((t) => t.id === tabId)) return inParked;
  }
  return new Set<string>();
}

function isSessionReferencedOutsideTab(state: WorkspaceState, sessionId: string, tabId: string): boolean {
  return getAllTabs(state).some((tab) => tab.id !== tabId && getTabSessionIds(state, tab.id).has(sessionId));
}

function isSessionReferenced(state: WorkspaceState, sessionId: string): boolean {
  return getAllTabs(state).some((tab) => getTabSessionIds(state, tab.id).has(sessionId));
}

function getDisposableSessionsForTab(state: WorkspaceState, tabId: string): TerminalSession[] {
  const result: TerminalSession[] = [];
  const seenBackends = new Set<string>();
  for (const sessionId of getTabSessionIds(state, tabId)) {
    if (isSessionReferencedOutsideTab(state, sessionId, tabId)) continue;
    const session = state.sessions[sessionId];
    if (!session) continue;
    const key = session.backendSessionId ?? session.id;
    if (seenBackends.has(key)) continue;
    seenBackends.add(key);
    result.push(session);
  }
  return result;
}

function sessionWorktreePath(session: TerminalSession | undefined): string {
  return session?.worktreePath ?? session?.cwd ?? "";
}

function getTabWorktreePath(state: WorkspaceState, tabId: string): string | null {
  for (const sessionId of getTabSessionIds(state, tabId)) {
    const path = sessionWorktreePath(state.sessions[sessionId]);
    if (path) return path;
  }
  for (const tab of getAllTabs(state)) {
    if (tab.id === tabId && tab.kind === "browser") {
      return tab.worktreePath ?? null;
    }
  }
  return null;
}

function findTabIdForSession(state: WorkspaceState, sessionId: string): string | null {
  for (const tab of getAllTabs(state)) {
    if (tab.kind === "browser") continue;
    if (getTabSessionIds(state, tab.id).has(sessionId)) return tab.id;
  }
  return null;
}

function clearWorktreeUnreadWhenRead(
  state: WorkspaceState,
  tabId: string,
  sourceState: WorkspaceState = state,
): WorkspaceState {
  const worktreePath = getTabWorktreePath(sourceState, tabId);
  if (!worktreePath) return state;
  const allTabs = getAllTabs(sourceState);
  const hasOtherUnreadTab = allTabs.some(
    (tab) => tab.id !== tabId && state.unreadTabIds[tab.id] && getTabWorktreePath(sourceState, tab.id) === worktreePath,
  );
  if (hasOtherUnreadTab) return state;
  const unreadWorktreePaths = { ...state.unreadWorktreePaths };
  delete unreadWorktreePaths[worktreePath];
  return { ...state, unreadWorktreePaths };
}

async function closeBackendSession(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  try {
    await services.closeTerminal(session.backendSessionId);
  } finally {
    terminalEventBus.clearSession(session.backendSessionId);
  }
}

async function closeBackendSessionAndWait(session: TerminalSession | undefined, services: WorkspaceServices) {
  if (!session?.backendSessionId) return;
  const backendSessionId = session.backendSessionId;
  const exitPromise = services.waitForTerminalExit(backendSessionId, LAST_TAB_EXIT_TIMEOUT_MS);
  try {
    await services.closeTerminal(backendSessionId);
    await exitPromise;
  } finally {
    terminalEventBus.clearSession(backendSessionId);
  }
}

function getActiveWorktree(state: WorkspaceState) {
  return state.worktrees.find((worktree) => worktree.path === state.activeWorktreePath) ?? state.worktrees[0] ?? null;
}

function nextTabLabel(worktree: Worktree, allTabs: WorkspaceTab[], sessions: Record<string, TerminalSession>) {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "") ?? "";
  const parts = branch.split("/");
  const base =
    parts[0] === "orca" && parts.length > 2
      ? parts.slice(2).join("/")
      : branch && branch !== "orca-lite"
        ? branch
        : "main";
  const count = allTabs.filter(
    (tab) => tab.kind !== "browser" && sessionWorktreePath(sessions[tab.sessionId]) === worktree.path,
  ).length + 1;
  return count === 1 ? base : `${base} (${count})`;
}

function mapBackendLifecycle(payload: TerminalLifecyclePayload): TerminalLifecycle {
  if (payload.state === "started") return "working";
  if (payload.state === "failed") return "failed";
  return "exited";
}

function createId(prefix: string) {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}:${randomPart}`;
}

  onLaunchAgent,
  defaultAgentId,
  onNavigateBrowserTab = () => undefined,
  onReloadBrowserTab = () => undefined,
  onSplitPane = () => undefined,
  onClosePane = () => undefined,
  onSetRatio = () => undefined,
  onSetGroupRatio = () => undefined,
  onSwapPanes = () => undefined,
  onFocusPane = () => undefined,
  onTitleChange = () => undefined,
  onBell,
  unreadTabIds,
  activityByTabId,
  leadingSpacer = 0,
  searchLeafId,
  onCloseSearch,
}: TerminalSplitViewProps) {
  const normalizedLayout = normalizeLayout(layout);
  const groups = normalizedLayout.tabGroups ?? {};
  const groupLayout = normalizedLayout.tabGroupLayout ?? null;
  const firstGroupId = firstTabGroupId(groupLayout);
  const dragSnapshotRef = useRef<DragFocusSnapshot | null>(null);
  const activeDragRef = useRef<WorkspaceDragData | null>(null);
  const [activeDrag, setActiveDrag] = useState<WorkspaceDragData | null>(null);
  const previewedTabIdRef = useRef<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 12 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  );

  const collisionDetection = workspaceCollisionDetection;

  const splitTerminalTab = (tabId: string, direction: PaneDirection) => {
    const tab = normalizedLayout.tabs.find((candidate) => candidate.id === tabId);
    if (!tab || tab.kind === "browser") return;
    const tabLayout = getTabPaneLayout(normalizedLayout, tab);
    const targetLeafId = tabLayout.activeLeafId ?? firstLeafId(tabLayout.root);
    onSplitPane(tab.id, targetLeafId, direction);
  };

  const restoreDragFocus = () => {
    const snapshot = dragSnapshotRef.current;
    if (snapshot?.activeTabId) onActivateTab(snapshot.activeTabId);
  };

  const clearDragState = () => {
    activeDragRef.current = null;
    setActiveDrag(null);
    dragSnapshotRef.current = null;
    previewedTabIdRef.current = null;
  };

  const handleDragStart = (event: DragStartEvent) => {
    const data = event.active.data.current;
    if (!isWorkspaceDragData(data)) return;
    activeDragRef.current = data;
    setActiveDrag(data);
    dragSnapshotRef.current = {
      activeTabId: normalizedLayout.activeTabId,
      focusedGroupId: normalizedLayout.focusedGroupId ?? null,
    };
    previewedTabIdRef.current = null;
  };

  const handleDragOver = (event: DragOverEvent) => {
    const active = activeDragRef.current;
    const overData = event.over?.data.current;
    if (!active || active.type !== "tab" || !isWorkspaceDropData(overData)) return;

    let previewTabId: string | null = null;
    if (overData.type === "tab" || overData.type === "pane-edge" || overData.type === "pane-leaf") {
      previewTabId = overData.tabId;
    }
    if (overData.type === "group-body" || overData.type === "group-edge") {
      previewTabId = groups[overData.groupId]?.activeTabId ?? groups[overData.groupId]?.tabIds[0] ?? null;
    }
    if (
      !previewTabId ||
      previewTabId === active.tabId ||
      previewTabId === normalizedLayout.activeTabId ||
      previewedTabIdRef.current === previewTabId
    )
      return;
    previewedTabIdRef.current = previewTabId;
    onActivateTab(previewTabId);
  };

  const executeDrop = (active: WorkspaceDragData, over: WorkspaceDropData | null) => {
    const command = resolveWorkspaceDropCommand(active, over);
    if (!command) return false;

    switch (command.type) {
      case "move-tab-to-group": {
        if (onMoveTabToGroup) {
          onMoveTabToGroup(command.tabId, command.targetGroupId, command.targetIndex);
          return true;
        }
        if (active.type === "tab" && command.targetGroupId === active.groupId && command.targetIndex !== undefined) {
          onReorderTab?.(command.tabId, command.targetIndex);
          return Boolean(onReorderTab);
        }
        return false;
      }
      case "move-tab-to-split":
        onMoveTabToSplit?.(command.tabId, command.targetGroupId, command.direction, command.position);
        return Boolean(onMoveTabToSplit);
      case "move-tab-to-pane-split": {
        const targetGroupId =
          Object.values(groups).find((g) => g.tabIds.includes(command.targetTabId))?.id ??
          firstGroupId ??
          "";
        const sourceTab = normalizedLayout.tabs.find((candidate) => candidate.id === command.sourceTabId);
        if (sourceTab?.kind === "browser") {
          onMoveTabToSplit?.(
            command.sourceTabId,
            targetGroupId,
            command.direction,
            command.position,
          );
          return Boolean(onMoveTabToSplit);
        }
        if (command.sourceTabId === command.targetTabId) {
          onSplitPane(command.targetTabId, command.targetLeafId, command.direction, {
            position: command.position,
          });
          return true;
        }
        onMoveTabToSplit?.(
          command.sourceTabId,
          targetGroupId,
          command.direction,
          command.position,
          { tabId: command.targetTabId, leafId: command.targetLeafId },
        );
        return Boolean(onMoveTabToSplit);
      }
      case "move-pane-to-pane-split": {
        const targetGroupId =
          Object.values(groups).find((g) => g.tabIds.includes(command.targetTabId))?.id ??
          firstGroupId ??
          "";
        const sourceLayout = normalizedLayout.layoutsByTabId?.[command.sourceTabId];
        const isSinglePane = !sourceLayout || sourceLayout.root.type === "leaf";
        if (isSinglePane) {
          onMoveTabToSplit?.(
            command.sourceTabId,
            targetGroupId,
            command.direction,
            command.position,
            { tabId: command.targetTabId, leafId: command.targetLeafId },
          );
          return Boolean(onMoveTabToSplit);
        }
        const sourceGroupId =
          Object.values(groups).find((g) => g.tabIds.includes(command.sourceTabId))?.id ??
          firstGroupId ??
          "";
        const detachedTabId = onDetachPaneToTab?.(command.sourceTabId, command.sourceLeafId, sourceGroupId);
        if (typeof detachedTabId !== "string" || !detachedTabId) return false;
        onMoveTabToSplit?.(
          detachedTabId,
          targetGroupId,
          command.direction,
          command.position,
          { tabId: command.targetTabId, leafId: command.targetLeafId },
        );
        return true;
      }
      case "detach-pane-to-tab":
        onDetachPaneToTab?.(command.sourceTabId, command.leafId, command.targetGroupId, command.targetIndex);
        return Boolean(onDetachPaneToTab);
      case "swap-panes":
        onSwapPanes(command.tabId, command.sourceLeafId, command.targetLeafId);
        return true;
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const active = activeDragRef.current;
    const overData = event.over?.data.current;
    const handled = active && isWorkspaceDropData(overData) ? executeDrop(active, overData) : false;
    if (!handled) restoreDragFocus();
    clearDragState();
  };

  const handleDragCancel = (_event: DragCancelEvent) => {
    restoreDragFocus();
    clearDragState();
  };

  const sharedGroupProps: Omit<TabGroupViewProps, "groupId" | "leadingSpacer"> = {
    layout: normalizedLayout,
    groups,
    sessions,
    onActivateTab,
    onCloseTab,
    onCloseOtherTabs,
    onCloseTabsToRight,
    onCloseTabsToLeft,
    onRenameTab,
    onToggleTabPin,
    onAddTab,
    onAddBrowserTab,
    onAddMarkdown,
    onAddMobileEmulator,
    onOpenSettings,
    agents,
    onLaunchAgent,
    defaultAgentId,
    onNavigateBrowserTab,
    onReloadBrowserTab,
    onSplitPane,
    onMoveTabToSplit,
    onClosePane,
    onSetRatio,
    onSwapPanes,
    onFocusPane,
    onTitleChange,
    onBell,
    unreadTabIds,
    activityByTabId,
    searchLeafId,
    onCloseSearch,
    splitTerminalTab,
    browserPanesVisible: activeDrag === null,
  };

  const overlayLabel =
    activeDrag?.type === "tab"
      ? normalizedLayout.tabs.find((tab) => tab.id === activeDrag.tabId)?.label ?? "Tab"
      : activeDrag?.type === "pane"
        ? "Terminal pane"
        : null;

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={collisionDetection}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDragEnd={handleDragEnd}
      onDragCancel={handleDragCancel}
    >
      <div className="relative flex flex-1 flex-col overflow-hidden bg-terminal" data-testid="terminal-layout">
        {groupLayout ? (
          <TabGroupLayoutRenderer
            node={groupLayout}
            path=""
            firstGroupId={firstGroupId}
            leadingSpacer={leadingSpacer}
            onSetGroupRatio={onSetGroupRatio}
            groupProps={sharedGroupProps}
          />
        ) : (
          <TabBar
            tabs={[]}
            activeTabId=""
            onActivate={onActivateTab}
            onClose={onCloseTab}
            onAdd={onAddTab}
            onAddBrowser={onAddBrowserTab}
            onAddMarkdown={onAddMarkdown}
            onAddMobileEmulator={onAddMobileEmulator}
            onOpenSettings={onOpenSettings}
            agents={agents}
            onLaunchAgent={onLaunchAgent}
            defaultAgentId={defaultAgentId}
            leadingSpacer={leadingSpacer}
          />
        )}
      </div>
      <DragOverlay dropAnimation={null}>
        {overlayLabel ? (
          <div data-testid="workspace-drag-overlay" className="rounded border border-border bg-card px-3 py-1.5 text-xs text-foreground shadow-lg">
            {overlayLabel}
          </div>
        ) : null}
      </DragOverlay>
    </DndContext>
  );
}

type TabGroupLayoutRendererProps = {
  node: TabGroupLayoutNode;
  path: string;
  firstGroupId: string | null;
  leadingSpacer: number;
  onSetGroupRatio: (path: string, ratio: number) => void;
  groupProps: Omit<TabGroupViewProps, "groupId" | "leadingSpacer">;
};

function TabGroupLayoutRenderer({ node, path, firstGroupId, leadingSpacer, onSetGroupRatio, groupProps }: TabGroupLayoutRendererProps) {
  if (node.type === "group") {
    return (
      <TabGroupView
        {...groupProps}
        groupId={node.groupId}
        leadingSpacer={node.groupId === firstGroupId ? leadingSpacer : 0}
      />
    );
  }

  const isHorizontal = node.direction === "horizontal";
  const ratio = node.ratio ?? 0.5;
  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden ${isHorizontal ? "flex-row" : "flex-col"}`}
      data-testid="tab-group-split"
      data-direction={node.direction}
    >
      <div className="relative min-h-0 min-w-0 overflow-hidden" style={{ flexBasis: `${ratio * 100}%`, flexGrow: 0, flexShrink: 0 }}>
        <TabGroupLayoutRenderer
          node={node.first}
          path={path ? `${path}.first` : "first"}
          firstGroupId={firstGroupId}
          leadingSpacer={leadingSpacer}
          onSetGroupRatio={onSetGroupRatio}
          groupProps={groupProps}
        />
      </div>
      <PaneResizeDivider
        direction={node.direction}
        ratio={ratio}
        ariaLabel="Resize tab groups"
        onRatioChange={(newRatio) => onSetGroupRatio(path, newRatio)}
      />
      <div className="relative min-h-0 min-w-0 flex-1 overflow-hidden" style={{ flexBasis: `${(1 - ratio) * 100}%`, flexGrow: 1, flexShrink: 1 }}>
        <TabGroupLayoutRenderer
          node={node.second}
          path={path ? `${path}.second` : "second"}
          firstGroupId={firstGroupId}
          leadingSpacer={leadingSpacer}
          onSetGroupRatio={onSetGroupRatio}
          groupProps={groupProps}
        />
      </div>
    </div>
  );
}

type TabGroupViewProps = {
  groupId: string;
  layout: LayoutState;
  groups: Record<string, TabGroup>;
  sessions: Record<string, TerminalSession>;
  leadingSpacer: number;
  onActivateTab: (tabId: string) => void;
  onCloseTab: (tabId: string) => void;
  onCloseOtherTabs?: (tabId: string) => void;
  onCloseTabsToRight?: (tabId: string) => void;
  onCloseTabsToLeft?: (tabId: string) => void;
  onRenameTab?: (tabId: string, label: string) => void;
  onToggleTabPin?: (tabId: string, pinned: boolean) => void;
  onAddTab: () => void;
  onAddBrowserTab: (url?: string) => void;
  onAddMarkdown?: () => void;
  onAddMobileEmulator?: () => void;
  onOpenSettings?: () => void;
  agents?: Array<{ name: string; command: string; args: string }>;
  onLaunchAgent?: (agent: { name: string; command: string; args: string }) => void;
  defaultAgentId?: string | null;
  onNavigateBrowserTab: (tabId: string, url: string) => void;
  onReloadBrowserTab: (tabId: string) => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onMoveTabToSplit?: (
    tabId: string,
    targetGroupId: string,
    direction: PaneDirection,
    position?: "first" | "second",
    targetPane?: { tabId: string; leafId: string },
  ) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSetRatio: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
  unreadTabIds?: Record<string, boolean>;
  activityByTabId?: Record<string, ActivitySummary | undefined>;
  searchLeafId?: string | null;
  onCloseSearch?: () => void;
  splitTerminalTab: (tabId: string, direction: PaneDirection) => void;
  browserPanesVisible: boolean;
};

function TabGroupView({
  groupId,
  layout,
  groups,
  sessions,
  leadingSpacer,
  onActivateTab,
  onCloseTab,
  onCloseOtherTabs,
  onCloseTabsToRight,
  onCloseTabsToLeft,
  onRenameTab,
  onToggleTabPin,
  onAddTab,
  onAddBrowserTab,
  onAddMarkdown,
  onAddMobileEmulator,
  onOpenSettings,
  agents,
  onLaunchAgent,
  defaultAgentId,
  onNavigateBrowserTab,
  onReloadBrowserTab,
  onSplitPane,
  onMoveTabToSplit,
  onClosePane,
  onSetRatio,
  onSwapPanes,
  onFocusPane,
  onTitleChange,
  onBell,
  unreadTabIds,
  activityByTabId,
  searchLeafId,
  onCloseSearch,
  splitTerminalTab,
  browserPanesVisible,
}: TabGroupViewProps) {
  const group = groups[groupId];
  if (!group) return null;
  const tabById = new Map(layout.tabs.map((tab) => [tab.id, tab]));
  const tabs = group.tabIds.map((tabId) => tabById.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab));
  const activeTab = tabs.find((tab) => tab.id === group.activeTabId) ?? tabs[0] ?? null;
  const activeTabLayout = activeTab ? getTabPaneLayout(layout, activeTab) : null;
  const isFocused = layout.focusedGroupId === groupId;

  const focusGroup = () => {
    if (activeTab) onActivateTab(activeTab.id);
  };

  const moveTabToSplitEdge = (tabId: string, edge: TabDropEdge) => {
    const { direction, position } = edgeToSplit(edge);
    onMoveTabToSplit?.(tabId, groupId, direction, position);
  };

  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 flex-col overflow-hidden bg-terminal ${isFocused ? "" : "opacity-95"}`}
      data-testid="tab-group-panel"
      data-tab-group-panel-id={groupId}
      onPointerDown={focusGroup}
      onFocusCapture={focusGroup}
    >
      <TabBar
        groupId={groupId}
        tabs={tabs}
        activeTabId={activeTab?.id ?? ""}
        unreadTabIds={unreadTabIds}
        activityByTabId={activityByTabId}
        onActivate={onActivateTab}
        onClose={onCloseTab}
        onCloseOthers={onCloseOtherTabs}
        onCloseToRight={onCloseTabsToRight}
        onCloseToLeft={onCloseTabsToLeft}
        onRenameTab={onRenameTab}
        onTogglePin={onToggleTabPin}
        onSplitRight={(tabId) => splitTerminalTab(tabId, "horizontal")}
        onSplitDown={(tabId) => splitTerminalTab(tabId, "vertical")}
        onMoveTabToSplit={moveTabToSplitEdge}
        onAdd={() => {
          focusGroup();
          onAddTab();
        }}
        onAddBrowser={(url) => {
          focusGroup();
          onAddBrowserTab(url);
        }}
        onAddMarkdown={
          onAddMarkdown
            ? () => {
                focusGroup();
                onAddMarkdown();
              }
            : undefined
        }
        onAddMobileEmulator={
          onAddMobileEmulator
            ? () => {
                focusGroup();
                onAddMobileEmulator();
              }
            : undefined
        }
        onOpenSettings={onOpenSettings}
        agents={agents}
        defaultAgentId={defaultAgentId}
        onLaunchAgent={
          onLaunchAgent
            ? (agent) => {
                focusGroup();
                onLaunchAgent(agent);
              }
            : undefined
        }
        leadingSpacer={leadingSpacer}
      />

      <TabGroupDropSurface groupId={groupId}>
        {!activeTab ? null : activeTab.kind === "browser" ? (
          <BrowserPane
            tab={activeTab}
            visible={browserPanesVisible}
            onNavigate={(url) => onNavigateBrowserTab(activeTab.id, url)}
            onReload={() => onReloadBrowserTab(activeTab.id)}
          />
        ) : activeTabLayout ? (
          <PaneRenderer
            node={activeTabLayout.root}
            tab={activeTab}
            tabLayout={activeTabLayout}
            sessions={sessions}
            groupFocused={isFocused}
            path=""
            searchLeafId={searchLeafId}
            onCloseSearch={onCloseSearch}
            onSplitPane={onSplitPane}
            onClosePane={onClosePane}
            onSetRatio={onSetRatio}
            onSwapPanes={onSwapPanes}
            onFocusPane={onFocusPane}
            onTitleChange={onTitleChange}
            onBell={onBell}
          />
        ) : null}
      </TabGroupDropSurface>
    </div>
  );
}

function getTabPaneLayout(layout: LayoutState, tab: WorkspaceTab): TabPaneLayout {
  const isBrowserTab = tab.kind === "browser";
  const fallbackLeafId = `leaf-default-${tab.id}`;
  return layout.layoutsByTabId?.[tab.id] ?? {
    root: { type: "leaf", leafId: fallbackLeafId },
    activeLeafId: fallbackLeafId,
    expandedLeafId: null,
    sessionIdsByLeafId: { [fallbackLeafId]: isBrowserTab ? "" : tab.sessionId },
  };
}

function firstLeafId(node: PaneNode): string {
  let current = node;
  while (current.type === "split") current = current.first;
  return current.leafId;
}

function firstTabGroupId(node: TabGroupLayoutNode | null): string | null {
  if (!node) return null;
  let current = node;
  while (current.type === "split") current = current.first;
  return current.groupId;
}

type PaneRendererProps = {
  node: PaneNode;
  tab: WorkspaceTab;
  tabLayout: TabPaneLayout;
  sessions: Record<string, TerminalSession>;
  groupFocused: boolean;
  path: string;
  searchLeafId?: string | null;
  onCloseSearch?: () => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onSetRatio: (tabId: string, path: string, ratio: number) => void;
  onSwapPanes: (tabId: string, sourceLeafId: string, targetLeafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

const PaneRenderer = React.memo(function PaneRenderer(props: PaneRendererProps) {
  const { node, tab, tabLayout, sessions, path } = props;
  if (node.type === "leaf") {
    const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
    const sessionId = tabLayout.sessionIdsByLeafId[node.leafId] ?? defaultSessionId;
    const session = sessions[sessionId] ?? FALLBACK_SESSION;
    return (
      <PaneLeafView
        leafId={node.leafId}
        tab={tab}
        session={session}
        isOnlyLeaf={tabLayout.root.type === "leaf"}
        isActive={props.groupFocused && tabLayout.activeLeafId === node.leafId}
        searchOpen={props.searchLeafId === node.leafId}
        onCloseSearch={props.onCloseSearch}
        onSplitPane={props.onSplitPane}
        onClosePane={props.onClosePane}
        onFocusPane={props.onFocusPane}
        onTitleChange={props.onTitleChange}
        onBell={props.onBell}
      />
    );
  }

  const isHorizontal = node.direction === "horizontal";
  const ratio = node.ratio ?? 0.5;
  return (
    <div
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden ${isHorizontal ? "flex-row" : "flex-col"}`}
      data-testid="pane-split"
      data-direction={node.direction}
    >
      <div className="relative min-h-0 min-w-0 overflow-hidden" style={{ flexBasis: `${ratio * 100}%`, flexGrow: 0, flexShrink: 0 }}>
        <PaneRenderer {...props} node={node.first} path={path ? `${path}.first` : "first"} />
      </div>
      <PaneResizeDivider
        direction={node.direction}
        ratio={ratio}
        ariaLabel="Resize terminal panes"
        onRatioChange={(newRatio) => props.onSetRatio(tab.id, path, newRatio)}
      />
      <div className="relative min-h-0 min-w-0 flex-1 overflow-hidden" style={{ flexBasis: `${(1 - ratio) * 100}%`, flexGrow: 1, flexShrink: 1 }}>
        <PaneRenderer {...props} node={node.second} path={path ? `${path}.second` : "second"} />
      </div>
    </div>
  );
});

type PaneLeafViewProps = {
  leafId: string;
  tab: WorkspaceTab;
  session: TerminalSession;
  isOnlyLeaf: boolean;
  isActive: boolean;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
  onSplitPane: (tabId: string, leafId: string, direction: PaneDirection, options?: SplitPaneOptions) => void;
  onClosePane: (tabId: string, leafId: string) => void;
  onFocusPane: (tabId: string, leafId: string) => void;
  onTitleChange: (tabId: string, title: string, sessionId?: string) => void;
  onBell?: (sessionId: string, tabId: string) => void;
};

const PaneLeafView = React.memo(function PaneLeafView({
  leafId,
  tab,
  session,
  isOnlyLeaf,
  isActive,
  searchOpen,
  onCloseSearch,
  onSplitPane,
  onClosePane,
  onFocusPane,
  onTitleChange,
  onBell,
}: PaneLeafViewProps) {
  const [isHoveredTop, setIsHoveredTop] = React.useState(false);
  const droppable = useDroppable({
    id: `pane-leaf:${tab.id}:${leafId}`,
    data: { type: "pane-leaf", tabId: tab.id, leafId },
  });
  const draggable = useDraggable({
    id: `pane:${tab.id}:${leafId}`,
    disabled: false,
    data: {
      type: "pane",
      tabId: tab.id,
      sourcePaneId: leafId,
      sourceSessionId: session.id,
    },
  });

  return (
    <div
      ref={droppable.setNodeRef}
      className={`relative flex h-full w-full min-h-0 min-w-0 overflow-hidden bg-terminal transition-all ${
        droppable.isOver ? "ring-2 ring-primary/80 ring-inset" : ""
      }`}
      data-testid="pane-leaf"
      data-leaf-id={leafId}
      data-tab-id={tab.id}
      data-dnd-type="pane-leaf"
      onClick={() => onFocusPane(tab.id, leafId)}
    >
      <PaneEdgeDropZones tabId={tab.id} leafId={leafId} />
      <div
        className="absolute inset-x-0 top-0 z-20 h-6"
        data-testid="pane-toolbar-hotspot"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={(event) => {
          const related = event.relatedTarget;
          if (!(related instanceof Element) || !related.closest('[data-testid="pane-toolbar"]')) setIsHoveredTop(false);
        }}
      />

      <div
        ref={draggable.setNodeRef}
        {...draggable.attributes}
        {...draggable.listeners}
        className={`absolute inset-x-0 top-0 z-30 flex h-6 items-center justify-end border-b border-border/30 bg-background/85 backdrop-blur-md px-2 text-[11px] text-muted-foreground transition-opacity duration-150 select-none cursor-grab touch-none active:cursor-grabbing ${
          isHoveredTop ? "pointer-events-auto opacity-100" : "pointer-events-none opacity-0"
        } ${draggable.isDragging ? "opacity-30" : ""}`}
        data-testid="pane-toolbar"
        data-dnd-type="pane"
        onMouseEnter={() => setIsHoveredTop(true)}
        onMouseLeave={() => setIsHoveredTop(false)}
      >
        <div className="flex items-center gap-0.5">
          <IconButton
            label="Split pane right"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "horizontal");
            }}
          >
            <Columns2 className="size-3" />
          </IconButton>
          <IconButton
            label="Split pane down"
            size="sm"
            className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={(event) => {
              event.stopPropagation();
              onSplitPane(tab.id, leafId, "vertical");
            }}
          >
            <Rows2 className="size-3" />
          </IconButton>
          {!isOnlyLeaf ? (
            <IconButton
              label="Close split view"
              size="sm"
              className="size-5 rounded p-0 text-muted-foreground/70 hover:bg-accent/60 hover:text-foreground"
              onPointerDown={(event) => event.stopPropagation()}
              onClick={(event) => {
                event.stopPropagation();
                onClosePane(tab.id, leafId);
              }}
            >
              <X className="size-3" />
            </IconButton>
          ) : null}
        </div>
      </div>

      <div className="h-full w-full min-h-0 flex-1 overflow-hidden">
        <TerminalPane
          session={session}
          active={isActive}
          onTitleChange={(title) => onTitleChange(tab.id, title, session.id)}
          onBell={() => onBell?.(session.id, tab.id)}
          searchOpen={searchOpen}
          onCloseSearch={onCloseSearch}
        />
      </div>
    </div>
  );
});

type PaneResizeDividerProps = {
  direction: PaneDirection;
  ratio: number;
  onRatioChange: (ratio: number) => void;
  ariaLabel?: string;
};

function PaneResizeDivider({ direction, ratio, onRatioChange, ariaLabel = "Resize terminal panes" }: PaneResizeDividerProps) {
  const dividerRef = useRef<HTMLDivElement>(null);
  const cleanupRef = useRef<(() => void) | null>(null);
  const isHorizontal = direction === "horizontal";

  useEffect(() => {
    return () => {
      if (cleanupRef.current) {
        cleanupRef.current();
        cleanupRef.current = null;
      }
    };
  }, []);

  const handlePointerDown = (event: React.PointerEvent) => {
    event.preventDefault();
    const parent = dividerRef.current?.parentElement;
    if (!parent) return;
    if (cleanupRef.current) {
      cleanupRef.current();
      cleanupRef.current = null;
    }
    document.body.style.cursor = isHorizontal ? "col-resize" : "row-resize";
