   172	pub fn save_session_to_path(
   173	    path: &Path,
   174	    session: &PersistedWorkspaceSession,
   175	) -> Result<(), IpcError> {
   176	    if let Some(parent) = path.parent() {
   177	        fs::create_dir_all(parent).map_err(|e| {
   178	            IpcError::new(
   179	                IpcErrorCode::IoError,
   180	                format!("Failed to create directory for session state: {}", e),
   181	            )
   182	        })?;
   183	    }
   184	
   185	    let serialized = serde_json::to_string_pretty(session).map_err(|e| {
   186	        IpcError::new(
   187	            IpcErrorCode::ParseError,
   188	            format!("Failed to serialize session state: {}", e),
   189	        )
   190	    })?;
   191	
   192	    let tmp_path = path.with_extension("json.tmp");
   193	
   194	    // Durable atomic write: write -> sync_all -> rename -> parent fsync
   195	    {
   196	        use std::io::Write;
   197	        let mut file = File::create(&tmp_path).map_err(|e| {
   198	            IpcError::new(
   199	                IpcErrorCode::IoError,
   200	                format!("Failed to create temporary session file: {}", e),
   201	            )
   202	        })?;
   203	        file.write_all(serialized.as_bytes()).map_err(|e| {
   204	            IpcError::new(
   205	                IpcErrorCode::IoError,
   206	                format!("Failed to write session state: {}", e),
   207	            )
   208	        })?;
   209	        file.sync_all().map_err(|e| {
   210	            IpcError::new(
   211	                IpcErrorCode::IoError,
   212	                format!("Failed to fsync temporary session file: {}", e),
   213	            )
   214	        })?;
   215	    }
   216	
   217	    fs::rename(&tmp_path, path).map_err(|e| {
   218	        IpcError::new(
   219	            IpcErrorCode::IoError,
   220	            format!("Failed to atomically rename session state file: {}", e),
   221	        )
   222	    })?;
   223	
   224	    // Parent directory fsync
   225	    if let Some(parent) = path.parent() {
   226	        if let Ok(dir_file) = File::open(parent) {
   227	            let _ = dir_file.sync_all();
   228	        }
   229	    }
   230	
   231	    Ok(())
   232	}
