     9	const browserLifecycleQueues = new Map<string, Promise<void>>();
    10	
    11	function enqueueBrowserLifecycle(browserId: string, operation: () => Promise<void>): Promise<void> {
    12	  const previous = browserLifecycleQueues.get(browserId) ?? Promise.resolve();
    13	  const next = previous.catch(() => undefined).then(operation);
    14	  browserLifecycleQueues.set(browserId, next);
    15	
    16	  const clearIfCurrent = () => {
    17	    if (browserLifecycleQueues.get(browserId) === next) {
    18	      browserLifecycleQueues.delete(browserId);
    19	    }
    20	  };
    21	  void next.then(clearIfCurrent, clearIfCurrent);
    22	
    23	  return next;
    24	}
