   137	  return {
   138	    root,
   139	    activeLeafId: layout.activeLeafId ? (leafIdMap.get(layout.activeLeafId) ?? layout.activeLeafId) : null,
   140	    expandedLeafId: layout.expandedLeafId ? (leafIdMap.get(layout.expandedLeafId) ?? layout.expandedLeafId) : null,
