+fn test_v2_v3_session_roundtrip_preserves_all_typed_fields() {
+    let dir = tempdir().unwrap();
+    let initial_file = dir.path().join("session_initial.json");
+    let resaved_file = dir.path().join("session_resaved.json");
+
